// Functions receive shared services and state through an explicit application context.
export function install(ctx){
async function usersPage(){if(ctx.profile?.role!=='admin'){ctx.render('home');return}ctx.shell(`${ctx.head('Gerenciar usuários','Aprove solicitações e defina os papéis de acesso.')}<div class="note">Administradores gerenciam acessos. Cada usuário aprovado mantém seus próprios clientes, produtos e orçamentos. Compartilhamento de uma base entre equipe ainda não está disponível.</div><section class="panel" style="margin-top:22px" id="user-list"><p class="loading">Carregando usuários…</p></section>`);try{const users=await ctx.api('/rest/v1/rpc/admin_users',{method:'POST',body:{}});ctx.$('#user-list').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Usuário / e-mail</th><th>Papel</th><th>Acesso</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${ctx.esc(u.username||'Sem nome')}</strong><br><span class="muted">${ctx.esc(u.email)}</span></td><td><select aria-label="Papel de ${ctx.esc(u.username||u.email)}" id="role-${u.id}" ${u.id===ctx.profile.id?'disabled':''}><option value="member" ${u.role==='member'?'selected':''}>Usuário</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrador</option></select></td><td><select aria-label="Acesso de ${ctx.esc(u.username||u.email)}" id="active-${u.id}" ${u.id===ctx.profile.id?'disabled':''}><option value="true" ${u.active?'selected':''}>Liberado</option><option value="false" ${!u.active?'selected':''}>Aguardando / bloqueado</option></select></td><td>${u.id===ctx.profile.id?'<span class="badge">Seu acesso</span>':`<button class="secondary small" data-user="${u.id}">Salvar acesso</button> <button class="secondary small" data-permissions="${u.id}">Permissões</button>`}</td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-permissions]').forEach(b=>b.onclick=()=>ctx.permissionEditor(b.dataset.permissions));document.querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await ctx.api('/rest/v1/rpc/admin_update_user',{method:'POST',body:{p_user:b.dataset.user,p_role:ctx.$('#role-'+b.dataset.user).value,p_active:ctx.$('#active-'+b.dataset.user).value==='true'}});ctx.toast('Permissões atualizadas.')}catch(e){ctx.toast(e.message)}finally{b.disabled=false}})}catch(e){ctx.$('#user-list').textContent=e.message}}
Object.assign(ctx,{usersPage});
}
